CREATE TABLE IF NOT EXISTS public."commission_rate_imports" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "source_sheet_id" text NOT NULL,
 "source_url" text NOT NULL,
 "source_title" text NOT NULL,
 "source_updated_at" date,
 "imported_at" timestamp with time zone DEFAULT now() NOT NULL,
 "imported_by" text DEFAULT 'codex'::text NOT NULL,
 "notes" text,
 "mall_record_count" integer NOT NULL,
 "marketplace_record_count" integer NOT NULL,
 CONSTRAINT "commission_rate_imports_mall_record_count_check" CHECK ((mall_record_count >= 0)),
 CONSTRAINT "commission_rate_imports_marketplace_record_count_check" CHECK ((marketplace_record_count >= 0)),
 CONSTRAINT "commission_rate_imports_pkey" PRIMARY KEY (id),
 CONSTRAINT "commission_rate_imports_source_sheet_id_source_updated_at_key" UNIQUE (source_sheet_id, source_updated_at)
);
ALTER TABLE public."commission_rate_imports" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public."commission_rate_imports" FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public."commission_rate_imports" TO service_role;
CREATE TABLE IF NOT EXISTS public."commission_rate_records" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "import_id" bigint NOT NULL,
 "seller_type" text NOT NULL,
 "cluster" text,
 "category_level_1" text,
 "category_level_2" text,
 "category_level_3" text,
 "category_level_4" text,
 "programme" text NOT NULL,
 "previous_rate_programme" numeric(7,6),
 "previous_rate_non_programme" numeric(7,6),
 "effective_rate_programme" numeric(7,6),
 "effective_rate_non_programme" numeric(7,6),
 "effective_date" date NOT NULL,
 "sst_rate" numeric(7,6) NOT NULL,
 "source_url" text NOT NULL,
 "source_section" text NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 CONSTRAINT "commission_rate_records_effective_rate_non_programme_check" CHECK (((effective_rate_non_programme >= (0)::numeric) AND (effective_rate_non_programme <= (1)::numeric))),
 CONSTRAINT "commission_rate_records_effective_rate_programme_check" CHECK (((effective_rate_programme >= (0)::numeric) AND (effective_rate_programme <= (1)::numeric))),
 CONSTRAINT "commission_rate_records_import_id_fkey" FOREIGN KEY (import_id) REFERENCES public."commission_rate_imports"(id) ON DELETE RESTRICT,
 CONSTRAINT "commission_rate_records_import_id_seller_type_cluster_categ_key" UNIQUE NULLS NOT DISTINCT (import_id, seller_type, cluster, category_level_1, category_level_2, category_level_3, category_level_4, programme, source_section),
 CONSTRAINT "commission_rate_records_pkey" PRIMARY KEY (id),
 CONSTRAINT "commission_rate_records_previous_rate_non_programme_check" CHECK (((previous_rate_non_programme >= (0)::numeric) AND (previous_rate_non_programme <= (1)::numeric))),
 CONSTRAINT "commission_rate_records_previous_rate_programme_check" CHECK (((previous_rate_programme >= (0)::numeric) AND (previous_rate_programme <= (1)::numeric))),
 CONSTRAINT "commission_rate_records_seller_type_check" CHECK ((seller_type = ANY (ARRAY['mall'::text, 'marketplace'::text]))),
 CONSTRAINT "commission_rate_records_sst_rate_check" CHECK (((sst_rate >= (0)::numeric) AND (sst_rate <= (1)::numeric)))
);
ALTER TABLE public."commission_rate_records" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public."commission_rate_records" FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public."commission_rate_records" TO service_role;
CREATE INDEX IF NOT EXISTS commission_rate_records_lookup_idx ON public.commission_rate_records USING btree (seller_type, source_section, cluster, category_level_1, category_level_2, category_level_3, category_level_4, effective_date);
CREATE TABLE IF NOT EXISTS public."commission_rate_import_notes" (
 "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
 "import_id" bigint NOT NULL,
 "position" integer NOT NULL,
 "note_type" text NOT NULL,
 "note_value" text NOT NULL,
 "created_at" timestamp with time zone DEFAULT now() NOT NULL,
 CONSTRAINT "commission_rate_import_notes_import_id_fkey" FOREIGN KEY (import_id) REFERENCES public."commission_rate_imports"(id) ON DELETE CASCADE,
 CONSTRAINT "commission_rate_import_notes_import_id_position_key" UNIQUE (import_id, "position"),
 CONSTRAINT "commission_rate_import_notes_pkey" PRIMARY KEY (id),
 CONSTRAINT "commission_rate_import_notes_position_check" CHECK (("position" > 0))
);
ALTER TABLE public."commission_rate_import_notes" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public."commission_rate_import_notes" FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public."commission_rate_import_notes" TO service_role;
CREATE TABLE IF NOT EXISTS public."store_voucher_presets" (
 "store_id" text NOT NULL,
 "tenant_id" text NOT NULL,
 "source_store_name" text NOT NULL,
 "non_campaign_average" numeric(5,2) NOT NULL,
 "campaign_average" numeric(5,2) NOT NULL,
 "non_campaign_rate" numeric(5,2) NOT NULL,
 "campaign_rate" numeric(5,2) NOT NULL,
 "source_sheet_id" text NOT NULL,
 "source_tab" text DEFAULT 'Final'::text NOT NULL,
 "source_row" integer NOT NULL,
 "source_updated_at" timestamp with time zone DEFAULT now() NOT NULL,
 "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
 CONSTRAINT "store_voucher_presets_campaign_average_check" CHECK (((campaign_average >= (0)::numeric) AND (campaign_average <= (100)::numeric))),
 CONSTRAINT "store_voucher_presets_campaign_rate_check" CHECK (((campaign_rate >= (0)::numeric) AND (campaign_rate <= (100)::numeric))),
 CONSTRAINT "store_voucher_presets_non_campaign_average_check" CHECK (((non_campaign_average >= (0)::numeric) AND (non_campaign_average <= (100)::numeric))),
 CONSTRAINT "store_voucher_presets_non_campaign_rate_check" CHECK (((non_campaign_rate >= (0)::numeric) AND (non_campaign_rate <= (100)::numeric))),
 CONSTRAINT "store_voucher_presets_pkey" PRIMARY KEY (store_id),
 CONSTRAINT "store_voucher_presets_source_row_check" CHECK ((source_row > 1)),
 CONSTRAINT "store_voucher_presets_store_id_fkey" FOREIGN KEY (store_id) REFERENCES public."stores"(id) ON DELETE CASCADE,
 CONSTRAINT "store_voucher_presets_tenant_id_fkey" FOREIGN KEY (tenant_id) REFERENCES public."tenants"(id) ON DELETE CASCADE
);
ALTER TABLE public."store_voucher_presets" ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public."store_voucher_presets" FROM PUBLIC,anon,authenticated,service_role;
GRANT SELECT ON public."store_voucher_presets" TO service_role;
CREATE INDEX IF NOT EXISTS store_voucher_presets_tenant_id_idx ON public.store_voucher_presets USING btree (tenant_id);
NOTIFY pgrst,'reload schema';
